import { redactSensitiveValues } from "../../internal/redact-values.js";
import { cutText } from "./text.js";
const ADAPTIVE_CARD_CONTENT_TYPE = "application/vnd.microsoft.card.adaptive";
const APPROVAL_ACTION = "bdk.tool-approval";
const ARGS_DISPLAY_MAX = 2_000;
export function parseApprovalSubmit(value) {
    const { action, sessionId, callId, decision } = value;
    if (action !== APPROVAL_ACTION ||
        typeof sessionId !== "string" ||
        sessionId === "" ||
        typeof callId !== "string" ||
        callId === "" ||
        (decision !== "approve" && decision !== "deny")) {
        return undefined;
    }
    return { sessionId, callId, decision };
}
export function approvalCardActivity(input) {
    const submit = (decision) => ({
        action: APPROVAL_ACTION,
        sessionId: input.sessionId,
        callId: input.callId,
        decision,
    });
    const args = formatArgs(input.args);
    return cardActivity({
        body: [
            { type: "TextBlock", text: `Approve ${input.toolLabel}?`, weight: "Bolder", wrap: true },
            ...(args === ""
                ? []
                : [{ type: "TextBlock", text: args, fontType: "Monospace", wrap: true }]),
        ],
        actions: [
            { type: "Action.Submit", title: "Approve", style: "positive", data: submit("approve") },
            { type: "Action.Submit", title: "Deny", style: "destructive", data: submit("deny") },
        ],
    });
}
export function resolvedApprovalCardActivity(input) {
    return cardActivity({
        body: [
            { type: "TextBlock", text: input.toolLabel, weight: "Bolder", wrap: true },
            {
                type: "TextBlock",
                text: resolvedApprovalText(input),
                color: input.decision === "approve" ? "Good" : "Attention",
                wrap: true,
            },
        ],
        actions: [],
    });
}
function resolvedApprovalText(input) {
    switch (input.reason) {
        case "timeout":
            return "Denied: nobody answered in time.";
        case "interrupt":
            return "Denied: the request stopped before anyone answered.";
        case undefined: {
            const verdict = input.decision === "approve" ? "Approved" : "Denied";
            return input.by === undefined ? verdict : `${verdict} by ${input.by}`;
        }
        default: {
            const unexpected = input.reason;
            return unexpected;
        }
    }
}
/** The card a click lands on once the call that waited for it is gone. */
export function closedApprovalCardActivity() {
    return cardActivity({
        body: [
            {
                type: "TextBlock",
                text: "This approval request expired.",
                wrap: true,
            },
        ],
        actions: [],
    });
}
function cardActivity(content) {
    return {
        type: "message",
        attachments: [
            {
                contentType: ADAPTIVE_CARD_CONTENT_TYPE,
                content: {
                    type: "AdaptiveCard",
                    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
                    version: "1.5",
                    ...content,
                },
            },
        ],
    };
}
function formatArgs(args) {
    if (args === undefined || args === null) {
        return "";
    }
    const redacted = redactSensitiveValues(args);
    const text = typeof redacted === "string" ? redacted : JSON.stringify(redacted, null, 2);
    return text.length <= ARGS_DISPLAY_MAX
        ? text
        : `${cutText(text, ARGS_DISPLAY_MAX)}… (${text.length} characters; the call uses all of them)`;
}
